gU7(){return"ReplyMate \u0938\u093f\u0930\u094d\u092b\u093c \u0906\u092a\u0915\u0947 \u091a\u0941\u0928\u0947 \u0939\u0941\u090f \u0910\u092a\u094d\u0938 \u0915\u0947 \u0928\u094b\u091f\u093f\u092b\u093c\u093f\u0915\u0947\u0936\u0928 \u0926\u0947\u0916\u0924\u093e \u0939\u0948\u0964"},
gUc(){return"\u0928\u094b\u091f\u093f\u092b\u093c\u093f\u0915\u0947\u0936\u0928 \u0910\u0915\u094d\u0938\u0947\u0938 \u0928\u0939\u0940\u0902 \u0926\u093f\u092f\u093e \u0917\u092f\u093e"},
gUb(){return"\u0907\u0938\u0915\u0947 \u092c\u093f\u0928\u093e \u092d\u0940 \u0928\u0940\u091a\u0947 \u0916\u0941\u0926 \u0932\u093f\u0916\u093e \u092f\u093e \u092a\u0947\u0938\u094d\u091f \u0915\u093f\u092f\u093e \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u091c\u0935\u093e\u092c \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u093e\u092e \u0915\u0930\u0924\u093e \u0939\u0948\u0964"},
gAp(){return"\u0905\u092a\u0928\u0940 \u0916\u0941\u0926 \u0915\u0940 AI \u0915\u0941\u0902\u091c\u0940"},
gPv(){return"AI \u0915\u093e \u0907\u0938\u094d\u0924\u0947\u092e\u093e\u0932"},
gKd(){return"\u091c\u0935\u093e\u092c, \u0905\u0928\u0941\u092e\u0924\u093f\u092f\u093e\u0901 \u0914\u0930 \u0928\u093f\u091c\u0924\u093e"},
gyF(){return"\u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0910\u092a\u094d\u0938"},
gPJ(){return"\u0905\u092d\u0940 \u091a\u0941\u0928\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u0941\u091b \u0928\u0939\u0940\u0902"},
PN(a,b){return""+b+" \u092e\u0947\u0902 \u0938\u0947 "+a+" \u091a\u0941\u0928\u0947 \u0917\u090f"},
gPI(){return"\u0907\u0938 \u0921\u093f\u0935\u093e\u0907\u0938 \u092a\u0930 \u0915\u094b\u0908 \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u092e\u0948\u0938\u0947\u091c\u093f\u0902\u0917 \u0910\u092a \u0928\u0939\u0940\u0902 \u0939\u0948\u0964"},
gPH(){return"\u091f\u0947\u0915\u094d\u0938\u094d\u091f \u092a\u0947\u0938\u094d\u091f \u092f\u093e \u091a\u0941\u0928\u0915\u0930 \u092d\u0940 \u0906\u092a ReplyMate \u0907\u0938\u094d\u0924\u0947\u092e\u093e\u0932 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"},
gPM(){return"\u091c\u093f\u0928 \u0910\u092a\u094d\u0938 \u0915\u0947 \u0928\u094b\u091f\u093f\u092b\u093f\u0915\u0947\u0936\u0928 ReplyMate \u092a\u0922\u093c \u0938\u0915\u0924\u093e \u0939\u0948"},
