gPO(){return"\u0915\u094b\u0908 \u0910\u092a \u092f\u0939\u093e\u0901 \u0938\u093f\u0930\u094d\u092b\u093c \u0924\u092c \u0906\u0924\u093e \u0939\u0948 \u091c\u092c \u0909\u0938\u0947 \u0928\u094b\u091f\u093f\u092b\u093f\u0915\u0947\u0936\u0928 \u092d\u0947\u091c\u0924\u0947 \u0926\u0947\u0916\u093e \u0917\u092f\u093e \u0939\u094b\u0964"},
gPL(){return"\u0907\u0902\u0938\u094d\u091f\u0949\u0932 \u0915\u093f\u090f \u0910\u092a\u094d\u0938 \u0915\u0940 \u0938\u0942\u091a\u0940 \u0928\u0939\u0940\u0902 \u092a\u0922\u093c\u0940 \u091c\u093e \u0938\u0915\u0940\u0964"},
gUT(){return"\u0930\u0940\u0921\u0930 \u0905\u092d\u0940 \u0915\u094d\u092f\u093e \u0915\u0930 \u0930\u0939\u093e \u0939\u0948"},
gUM(){return"\u0930\u093f\u092b\u093c\u094d\u0930\u0947\u0936"},
gUL(){return"Android \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 \u0916\u094b\u0932\u0947\u0902"},
gUI(){return"\u0907\u0938 \u092b\u093c\u094b\u0928 \u092e\u0947\u0902 \u0916\u094b\u0932\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u094b\u0908 \u090f\u0915\u094d\u0938\u0947\u0938\u093f\u092c\u093f\u0932\u093f\u091f\u0940 \u0938\u094d\u0915\u094d\u0930\u0940\u0928 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 \u2192 \u090f\u0915\u094d\u0938\u0947\u0938\u093f\u092c\u093f\u0932\u093f\u091f\u0940 \u092e\u0947\u0902 \u0926\u0947\u0916\u0947\u0902\u0964"},
gUJ(){return"\u0928\u0947\u091f\u093f\u0935 \u0938\u093e\u0907\u0921 \u0938\u0947 \u0905\u092d\u0940 \u0915\u094b\u0908 \u091c\u0935\u093e\u092c \u0928\u0939\u0940\u0902 \u0906\u092f\u093e\u0964"},
gUP(){return"\u0938\u0947\u0935\u093e: \u091a\u0932 \u0928\u0939\u0940\u0902 \u0930\u0939\u0940"},
